window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["kubernetes-24-config-secrets-br-access-control"]={"html":"Config · Secrets &amp; Access Control — Kubernetes Book 02\r\n\r\n<a href=\"#toc\">▤ TOC</a>\r\n\r\n\r\n<div class=\"page cover\">\r\n<div class=\"orb\"></div>\r\n<div class=\"orb\"></div>\r\n<div class=\"wheel\">🔐</div>\r\n<h1 id=\"config-secrets-amp-access-control\">CONFIG · SECRETS<br />&amp; ACCESS CONTROL</h1>\r\n<div class=\"sub\">Book 02 of the series — stop baking config into images. ConfigMaps for plain settings, Secrets for sensitive data (and the base64 truth), RBAC for who may do what, ServiceAccounts for workload identity, SecurityContext &amp; Pod Security Standards for hardening, and Requests/Limits + QoS for the resource contract.</div>\r\n<div class=\"row\">\r\n<div class=\"glass\">⚙️ ConfigMap<small>plain config</small></div>\r\n<div class=\"glass\">🔐 Secret<small>sensitive data</small></div>\r\n<div class=\"glass\">🪪 RBAC<small>who may do what</small></div>\r\n<div class=\"glass\">👷 ServiceAccount<small>workload identity</small></div>\r\n</div>\r\n<div class=\"row\">\r\n<div class=\"glass\">🛡️ SecurityContext<small>pod hardening</small></div>\r\n<div class=\"glass\">🚨 PSS<small>three levels</small></div>\r\n<div class=\"glass\">📊 Requests/Limits<small>the budget</small></div>\r\n<div class=\"glass\">🎚️ QoS<small>eviction order</small></div>\r\n</div>\r\n<div class=\"ver\">K8S KNOWLEDGE BASE · BOOK 02 · CONTINUES BOOK 01 · 2026</div>\r\n</div>\r\n\r\n\r\n<div class=\"page\">\r\n<div class=\"pghead\"><span class=\"chip\">📖</span><h2 id=\"contents-click-any-row\">Contents — click any row</h2><span class=\"dbadge\">6 parts · 24 chapters</span></div>\r\n<div class=\"tocgrid\">\r\n<div class=\"tocpart\">Part I · Config Injection</div>\r\n<a href=\"#ch01\"><span class=\"cb\"></span><span class=\"tnum\">CH 01</span>ConfigMaps — What &amp; Why<span class=\"dots\"></span><span class=\"tp\">p.3</span></a>\r\n<a href=\"#ch02\"><span class=\"cb\"></span><span class=\"tnum\">CH 02</span>Creating &amp; Mounting ConfigMaps<span class=\"dots\"></span><span class=\"tp\">p.4</span></a>\r\n<a href=\"#ch03\"><span class=\"cb\"></span><span class=\"tnum\">CH 03</span>Hot-Reload — What Actually Updates<span class=\"dots\"></span><span class=\"tp\">p.5</span></a>\r\n<div class=\"tocpart\">Part II · Secrets</div>\r\n<a href=\"#ch04\"><span class=\"cb\"></span><span class=\"tnum\">CH 04</span>Secrets — vs ConfigMaps<span class=\"dots\"></span><span class=\"tp\">p.6</span></a>\r\n<a href=\"#ch05\"><span class=\"cb\"></span><span class=\"tnum\">CH 05</span>Secret Types &amp; Creation<span class=\"dots\"></span><span class=\"tp\">p.7</span></a>\r\n<a href=\"#ch06\"><span class=\"cb\"></span><span class=\"tnum\">CH 06</span>Mounting Secrets + imagePullSecrets<span class=\"dots\"></span><span class=\"tp\">p.8</span></a>\r\n<a href=\"#ch07\"><span class=\"cb\"></span><span class=\"tnum\">CH 07</span>Base64 ≠ Encryption — The Truth<span class=\"dots\"></span><span class=\"tp\">p.9</span></a>\r\n<div class=\"tocpart\">Part III · Access Control (RBAC)</div>\r\n<a href=\"#ch08\"><span class=\"cb\"></span><span class=\"tnum\">CH 08</span>RBAC — The Big Idea<span class=\"dots\"></span><span class=\"tp\">p.10</span></a>\r\n<a href=\"#ch09\"><span class=\"cb\"></span><span class=\"tnum\">CH 09</span>Roles &amp; RoleBindings<span class=\"dots\"></span><span class=\"tp\">p.11</span></a>\r\n<a href=\"#ch10\"><span class=\"cb\"></span><span class=\"tnum\">CH 10</span>ClusterRoles &amp; When to Use Which<span class=\"dots\"></span><span class=\"tp\">p.12</span></a>\r\n<a href=\"#ch11\"><span class=\"cb\"></span><span class=\"tnum\">CH 11</span>ServiceAccounts<span class=\"dots\"></span><span class=\"tp\">p.13</span></a>\r\n<div class=\"tocpart\">Part IV · Hardening &amp; Resources</div>\r\n<a href=\"#ch12\"><span class=\"cb\"></span><span class=\"tnum\">CH 12</span>SecurityContext<span class=\"dots\"></span><span class=\"tp\">p.14</span></a>\r\n<a href=\"#ch13\"><span class=\"cb\"></span><span class=\"tnum\">CH 13</span>Pod Security Standards<span class=\"dots\"></span><span class=\"tp\">p.15</span></a>\r\n<a href=\"#ch14\"><span class=\"cb\"></span><span class=\"tnum\">CH 14</span>Requests &amp; Limits<span class=\"dots\"></span><span class=\"tp\">p.16</span></a>\r\n<a href=\"#ch15\"><span class=\"cb\"></span><span class=\"tnum\">CH 15</span>QoS Classes<span class=\"dots\"></span><span class=\"tp\">p.17</span></a>\r\n<div class=\"tocpart\">Part V · Labs</div>\r\n<a href=\"#lab1\"><span class=\"cb\"></span><span class=\"tnum\">LAB 1</span>ConfigMap: Prove Env ≠ Hot-Reload<span class=\"dots\"></span><span class=\"tp\">p.18</span></a>\r\n<a href=\"#lab2\"><span class=\"cb\"></span><span class=\"tnum\">LAB 2</span>Secret: Encoded, Not Encrypted<span class=\"dots\"></span><span class=\"tp\">p.19</span></a>\r\n<a href=\"#lab3\"><span class=\"cb\"></span><span class=\"tnum\">LAB 3</span>RBAC: Can-I as a ServiceAccount<span class=\"dots\"></span><span class=\"tp\">p.20</span></a>\r\n<a href=\"#lab4\"><span class=\"cb\"></span><span class=\"tnum\">LAB 4</span>Trigger an OOMKill on Purpose<span class=\"dots\"></span><span class=\"tp\">p.21</span></a>\r\n<div class=\"tocpart\">Part VI · Prove It</div>\r\n<a href=\"#quiz\"><span class=\"cb\"></span><span class=\"tnum\">QUIZ</span>Self-Check Quiz<span class=\"dots\"></span><span class=\"tp\">p.22</span></a>\r\n<a href=\"#key\"><span class=\"cb\"></span><span class=\"tnum\">KEY</span>Answer Key + Scoring<span class=\"dots\"></span><span class=\"tp\">p.23</span></a>\r\n<a href=\"#gloss\"><span class=\"cb\"></span><span class=\"tnum\">GLOSS</span>Glossary<span class=\"dots\"></span><span class=\"tp\">p.24</span></a>\r\n<a href=\"#cheat\"><span class=\"cb\"></span><span class=\"tnum\">CHEAT</span>One-Page Cheat Sheet<span class=\"dots\"></span><span class=\"tp\">p.25</span></a>\r\n<a href=\"#finale\"><span class=\"cb\"></span><span class=\"tnum\">FINALE</span>Where to Next → Book 03<span class=\"dots\"></span><span class=\"tp\">p.26</span></a>\r\n</div>\r\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Assumes Book 01 complete.</b> You already know Pods, ReplicaSets, Deployments, self-healing, and NodePort. This book adds the config layer (I–II), the permission layer (III), and the hardening/resource layer (IV) — then proves it all with labs.</div></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span>◀ cover · start ▶</span><span>Page 2</span></div>\r\n</div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 01</span><h2 id=\"configmaps-what-amp-why\">⚙️ ConfigMaps — What &amp; Why</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\r\n<p>The problem: bake <code>LOG_LEVEL=debug</code> into your image and every environment change = <b>rebuild, re-push, re-pull</b>. A ConfigMap decouples configuration <b>from</b> the image: one image, many configs.</p>\r\n<div class=\"grid2\">\r\n<div class=\"card\"><div class=\"zlabel\">❌ Config baked into the image</div>\r\n<div class=\"mtree\">app:v1 + <em>debug</em>  → build → push\r\napp:v1 + <em>info</em>    → build → push\r\napp:v1 + <em>prod</em>    → build → push\r\n<span class=\"g\">3 images, 3 pipelines, 3 chances to drift</span></div></div>\r\n<div class=\"card\"><div class=\"zlabel\">✅ Config injected at runtime</div>\r\n<div class=\"mtree\">app:v1 <span class=\"g\">(built ONCE)</span>\r\n  + cfg-debug   <span class=\"g\">→ dev cluster</span>\r\n  + cfg-staging <span class=\"g\">→ staging</span>\r\n  + cfg-prod    <span class=\"g\">→ prod</span>\r\n<span class=\"g\">same image everywhere — only the map differs</span></div></div>\r\n</div>\r\n<h3 id=\"create-one-three-ways\">🛠️ Create one — three ways</h3>\r\n<div class=\"term\"><span class=\"p\">$</span> kubectl create configmap app-config <span class=\"y\">--from-literal</span>=LOG_LEVEL=debug\r\n<span class=\"p\">$</span> kubectl create configmap app-conf <span class=\"y\">--from-file</span>=app.conf\r\n<span class=\"p\">$</span> kubectl apply -f configmap.yaml   <span class=\"g\"># the declarative way (CH 02)</span>\r\n<span class=\"g\">configmap/app-config created</span></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> a ConfigMap is a named bag of key/value pairs (or files) that lives <i>inside a namespace</i> — injected into Pods as <b>env vars</b> or <b>files</b>. It's the Kubernetes take on 12-factor config: <i>config belongs to the environment, not the artifact</i>.</div></div>\r\n<p>⏭️ How do Pods actually consume one? ← <a href=\"#ch02\">CH 02: Creating &amp; Mounting</a></p>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#toc\">▤ TOC</a> · <a href=\"#ch02\">next ▶</a></span><span>Page 3</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 02</span><h2 id=\"creating-amp-mounting-configmaps\">📥 Creating &amp; Mounting ConfigMaps</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<div class=\"term\"><span class=\"c\">apiVersion</span>: v1\r\n<span class=\"c\">kind</span>: ConfigMap\r\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: app-config }\r\n<span class=\"c\">data</span>:\r\n  <span class=\"y\">LOG_LEVEL</span>: <span class=\"m\">\"debug\"</span>          <span class=\"g\"># simple key → env var</span>\r\n  <span class=\"y\">app.conf</span>: <span class=\"m\">|</span>                  <span class=\"g\"># whole file as one key</span>\r\n    listen 8080\r\n    workers 4</div>\r\n<h3 id=\"two-consumption-methods-they-behave-differently\">🔌 Two consumption methods — they behave differently</h3>\r\n<div class=\"term\"><span class=\"c\">spec</span>:\r\n  <span class=\"c\">containers</span>:\r\n  - <span class=\"c\">name</span>: app\r\n    <span class=\"c\">image</span>: myapp:2.0\r\n    <span class=\"c\">env</span>:                       <span class=\"g\"># METHOD 1 · single keys as env vars</span>\r\n    - <span class=\"c\">name</span>: LOG_LEVEL\r\n      <span class=\"c\">valueFrom</span>:\r\n        <span class=\"c\">configMapKeyRef</span>: { <span class=\"c\">name</span>: app-config, <span class=\"c\">key</span>: LOG_LEVEL }\r\n    <span class=\"c\">envFrom</span>:                   <span class=\"g\"># …or import EVERY key as env</span>\r\n    - <span class=\"c\">configMapRef</span>: { <span class=\"c\">name</span>: app-config }\r\n    <span class=\"c\">volumeMounts</span>:              <span class=\"g\"># METHOD 2 · keys as FILES</span>\r\n    - { <span class=\"c\">name</span>: cfg, <span class=\"c\">mountPath</span>: <span class=\"m\">/etc/app</span> }\r\n  <span class=\"c\">volumes</span>:\r\n  - <span class=\"c\">name</span>: cfg\r\n    <span class=\"c\">configMap</span>: { <span class=\"c\">name</span>: app-config }  <span class=\"g\"># each key becomes a file</span></div>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th></th><th>📦 As env vars</th><th>📁 As volume files</th></tr>\r\n<tr><td><b>Shape</b></td><td>flat <code>KEY=value</code></td><td>real files (<code>app.conf</code>, nested keys ok)</td></tr>\r\n<tr><td><b>Update behavior</b></td><td><span class=\"bad\">never</span> — snapshot at container start</td><td><span class=\"ok\">auto-updated</span> by kubelet (~1 min, CH 03)</td></tr>\r\n<tr><td><b>Best for</b></td><td>simple toggles, ports, feature flags</td><td>config files, templates, anything the app re-reads</td></tr>\r\n</table></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Rule of thumb:</b> env vars are a <b>snapshot</b>, volume mounts are a <b>live feed</b>. Choose by asking: <i>\"does my app re-read its config file, or read the environment once at boot?\"</i></div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch01\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch03\">next ▶</a></span><span>Page 4</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 03</span><h2 id=\"hot-reload-what-actually-updates\">🔄 Hot-Reload — What Actually Updates</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<p>The most-Googled ConfigMap question. The answer is a <b>2×2 matrix</b> — and one famous trap.</p>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Consumed as…</th><th>ConfigMap changes → Pod sees…</th><th>Why</th></tr>\r\n<tr><td><b>Env var</b></td><td><span class=\"bad\">❌ Never</span></td><td>environment is fixed at container start (Linux process rules, not k8s')</td></tr>\r\n<tr><td><b>Volume file</b></td><td><span class=\"ok\">✅ Yes</span> — eventually (~1 min)</td><td>kubelet syncs mounted files on its sync period</td></tr>\r\n<tr><td><b>Volume via <code>subPath</code></b></td><td><span class=\"bad\">❌ Never</span></td><td>subPath mounts a <i>copy</i>; the symlink chain is broken</td></tr>\r\n<tr><td><b>Env + app restart</b></td><td><span class=\"ok\">✅ Yes</span> (on next start)</td><td>new container = fresh snapshot</td></tr>\r\n</table></div>\r\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>\"Eventually\" means eventually:</b> updates ride the kubelet sync period plus the API watch cache — <b>up to ~1 minute of delay</b>, in no guaranteed order. Apps that cache config at startup (Java, many frameworks) still see <b>nothing</b> until they re-read the file. The file changing ≠ your app noticing.</div></div>\r\n<div class=\"term mini\"><span class=\"c\">volumes</span>:\r\n- <span class=\"c\">name</span>: cfg\r\n  <span class=\"c\">configMap</span>: { <span class=\"c\">name</span>: app-config, <span class=\"c\">immutable</span>: <span class=\"y\">true</span> }  <span class=\"g\"># freeze it entirely</span></div>\r\n<ul>\r\n<li>🧊 <code>immutable: true</code> — rejects all updates (and can't be un-set without delete/recreate). Trade-off: <b>zero hot-reload</b> in exchange for protecting against accidental changes + better kubelet performance at scale.</li>\r\n<li>🔁 Common production pattern: app watches its config file (or a sidecar triggers a reload endpoint) — k8s delivers the file, <i>your app</i> decides to care.</li>\r\n</ul>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Exam-grade answer:</b> <i>volume-mounted ConfigMaps auto-update (eventually, ~1 min); env vars and subPath mounts never update — a Pod restart is the only guaranteed way to re-read env config.</i> Lab 1 proves it.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch02\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch04\">next ▶</a></span><span>Page 5</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 04</span><h2 id=\"secrets-vs-configmaps\">🔐 Secrets — vs ConfigMaps</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<p>Same mechanism, different cargo. A Secret holds data you'd flinch to print in a <code>git log</code>: passwords, tokens, TLS keys, registry credentials.</p>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Aspect</th><th>⚙️ ConfigMap</th><th>🔐 Secret</th></tr>\r\n<tr><td><b>Cargo</b></td><td>plain config</td><td>sensitive data (passwords, certs, tokens)</td></tr>\r\n<tr><td><b>Values on disk</b></td><td>plain text</td><td><b>base64-encoded</b> (<code>data</code>) — CH 07 for what that does and doesn't mean</td></tr>\r\n<tr><td><b>Value size</b></td><td>~1 MiB</td><td>~1 MiB</td></tr>\r\n<tr><td><b>Consumed as</b></td><td>env / volume</td><td>env / volume — <b>same two methods</b></td></tr>\r\n<tr><td><b>Default visibility</b></td><td>anyone who can <code>get</code> it</td><td>gated by <b>RBAC</b> — reading secrets is its own permission (Part III)</td></tr>\r\n<tr><td><b>Write convenience</b></td><td><code>data</code></td><td><code>data</code> (pre-encoded) <b>or</b> <code>stringData</code> (plain — API encodes for you)</td></tr>\r\n</table></div>\r\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Do not skip this:</b> base64 is <b>encoding, not encryption</b> — anyone can decode it with one command. By default, Secrets sit in etcd unencrypted. Real protection = etcd encryption-at-rest + tight RBAC (Part III). Full autopsy in CH 07.</div></div>\r\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl create secret generic db-pass <span class=\"y\">--from-literal</span>=PASSWORD=<span class=\"m\">\"s3cr3t\"</span>\r\n<span class=\"g\">secret/db-pass created</span></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Mental model:</b> ConfigMap = the whiteboard in the apartment (anyone may read). Secret = the safe (base64 = the box it ships in; RBAC = who has the key). Same delivery mechanism, different trust level.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch03\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch05\">next ▶</a></span><span>Page 6</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 05</span><h2 id=\"secret-types-amp-creation\">🏷️ Secret Types &amp; Creation</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<p><code>type</code> is a label that tells Kubernetes (and tooling) what shape the keys should take. The default is <code>Opaque</code> — \"just key/values\".</p>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Type</th><th>Required keys</th><th>Used by</th></tr>\r\n<tr><td><code>Opaque</code> <span class=\"stbadge st-comp\">default</span></td><td>anything you like</td><td>app passwords, API keys, generic data</td></tr>\r\n<tr><td><code>kubernetes.io/dockerconfigjson</code></td><td><code>.dockerconfigjson</code></td><td><b>imagePullSecrets</b> — private registry auth (CH 06)</td></tr>\r\n<tr><td><code>kubernetes.io/tls</code></td><td><code>tls.crt</code> + <code>tls.key</code></td><td>Ingress TLS termination (Book 03)</td></tr>\r\n<tr><td><code>kubernetes.io/basic-auth</code></td><td><code>username</code>, <code>password</code></td><td>basic-auth integrations</td></tr>\r\n<tr><td><code>kubernetes.io/service-account-token</code></td><td>— (API-managed)</td><td>SA tokens — mostly automatic since v1.24 (CH 11)</td></tr>\r\n</table></div>\r\n<h3 id=\"creation-imperative-amp-declarative\">🛠️ Creation — imperative &amp; declarative</h3>\r\n<div class=\"term\"><span class=\"p\">$</span> kubectl create secret generic db-pass <span class=\"y\">--from-literal</span>=PASSWORD=<span class=\"m\">\"s3cr3t\"</span>\r\n<span class=\"p\">$</span> kubectl create secret docker-registry regcred \\\r\n    <span class=\"y\">--docker-server</span>=registry.example.com <span class=\"y\">--docker-username</span>=ci \\\r\n    <span class=\"y\">--docker-password</span>=<span class=\"r\">$TOKEN</span>\r\n<span class=\"p\">$</span> kubectl create secret tls web-tls <span class=\"y\">--cert</span>=tls.crt <span class=\"y\">--key</span>=tls.key</div>\r\n<div class=\"term mini\"><span class=\"c\">apiVersion</span>: v1\r\n<span class=\"c\">kind</span>: Secret\r\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: db-pass }\r\n<span class=\"c\">type</span>: Opaque\r\n<span class=\"c\">stringData</span>:                 <span class=\"g\"># WRITE-only convenience — plain text in</span>\r\n  <span class=\"y\">PASSWORD</span>: <span class=\"m\">\"s3cr3t\"</span>        <span class=\"g\"># the API base64-encodes it into `data`</span></div>\r\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><code>stringData</code> never comes back out — <code>kubectl get secret -o yaml</code> always shows <code>data</code> with base64 values. Handy for readable YAML in Git pipelines (with the Git-secrets caveat of CH 07).</div></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Remember the pair:</b> <code>dockerconfigjson</code> → pulling images · <code>tls</code> → serving HTTPS. These two built-in types are the exam's favorites because they have <b>mandatory key names</b>.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch04\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch06\">next ▶</a></span><span>Page 7</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 06</span><h2 id=\"mounting-secrets-imagepullsecrets\">📤 Mounting Secrets + imagePullSecrets</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<p>Same two doors as ConfigMaps — env vars (snapshot) and volumes (live feed) — plus a third, special-purpose door for the registry.</p>\r\n<div class=\"term\"><span class=\"c\">spec</span>:\r\n  <span class=\"c\">containers</span>:\r\n  - <span class=\"c\">name</span>: app\r\n    <span class=\"c\">image</span>: myapp:2.0\r\n    <span class=\"c\">env</span>:\r\n    - <span class=\"c\">name</span>: DB_PASSWORD\r\n      <span class=\"c\">valueFrom</span>:\r\n        <span class=\"c\">secretKeyRef</span>: { <span class=\"c\">name</span>: db-pass, <span class=\"c\">key</span>: PASSWORD }\r\n    <span class=\"c\">volumeMounts</span>:\r\n    - { <span class=\"c\">name</span>: sec, <span class=\"c\">mountPath</span>: <span class=\"m\">/etc/secrets</span>, <span class=\"c\">readOnly</span>: <span class=\"y\">true</span> }\r\n  <span class=\"c\">volumes</span>:\r\n  - <span class=\"c\">name</span>: sec\r\n    <span class=\"c\">secret</span>: { <span class=\"c\">secretName</span>: db-pass }   <span class=\"g\"># keys → files, kubelet-synced</span></div>\r\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Prefer the volume door for sensitive data:</b> env vars leak casually — they appear in <code>kubectl describe</code>, crash dumps, child processes (<code>/proc/&lt;pid&gt;/environ</code>), and some error reporters. A read-only file at a known path is easier to contain. (Hot-reload semantics from CH 03 apply identically to Secret volumes.)</div></div>\r\n<h3 id=\"imagepullsecrets-auth-for-pulling-images\">🖼️ imagePullSecrets — auth for pulling images</h3>\r\n<div class=\"term\"><span class=\"g\"># one-time: create the registry credential (CH 05)</span>\r\n<span class=\"p\">$</span> kubectl create secret docker-registry regcred …\r\n<span class=\"g\"># then attach it to the ServiceAccount — every Pod in that\r\n# namespace using this SA inherits it (recommended way)</span>\r\n<span class=\"p\">$</span> kubectl patch serviceaccount default <span class=\"y\">-p</span> \\\r\n  <span class=\"m\">'{\"imagePullSecrets\":[{\"name\":\"regcred\"}]}'</span>\r\n<span class=\"g\"># or per-Pod in the spec:</span>\r\n<span class=\"c\">spec</span>:\r\n  <span class=\"c\">imagePullSecrets</span>:\r\n  - { <span class=\"c\">name</span>: regcred }</div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Three doors, one rule:</b> env = snapshot · volume = live feed · <code>imagePullSecrets</code> = only for the <b>kubelet pulling images</b> (never appears inside your container). SA-level attachment wins over per-Pod because it covers every Pod the SA runs.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch05\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch07\">next ▶</a></span><span>Page 8</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 07</span><h2 id=\"base64-encryption-the-truth\">🔓 Base64 ≠ Encryption — The Truth</h2><span class=\"dbadge\">🟡 6 MIN · MUST-KNOW</span></div>\r\n<p>The single most common Secrets misconception. Watch it die in one command:</p>\r\n<div class=\"termbar\"><span></span><span></span><span></span></div>\r\n<div class=\"term tbr\"><span class=\"p\">$</span> kubectl get secret db-pass -o jsonpath=<span class=\"m\">'{.data.PASSWORD}'</span>\r\n<span class=\"y\">czNjcjN0</span>               <span class=\"g\"># looks safe… it is not</span>\r\n<span class=\"p\">$</span> <span class=\"c\">echo</span> czNjcjN0 | <span class=\"c\">base64</span> <span class=\"y\">-d</span>\r\ns3cr3t                 <span class=\"g\"># decoded by anyone, instantly</span></div>\r\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Base64 is a transport encoding</b> — it makes binary-ish data YAML-safe. It's a locked box made of cardboard: the point is safe shipping, not safe keeping. <b>Anyone</b> with <code>get secrets</code> permission reads every \"hidden\" value.</div></div>\r\n<h3 id=\"the-four-real-layers-of-secret-protection\">🧅 The four real layers of Secret protection</h3>\r\n<div class=\"mtree\"><b>Layer 1 · Encoding</b>      base64  <span class=\"g\">NOT protection — just transport</span>\r\n<b>Layer 2 · Encryption at rest</b>  EncryptionConfiguration on kube-apiserver\r\n                <span class=\"g\">(aescbc / secretbox / KMS plugin) — encrypts in etcd</span>\r\n<b>Layer 3 · RBAC</b>           who may <u>get/list</u> secrets at all  <span class=\"g\">← Part III</span>\r\n<b>Layer 4 · Externalization</b>  External Secrets / Vault — cluster\r\n                <span class=\"g\">never stores the real value long-term</span></div>\r\n<ul>\r\n<li>🚫 Never commit raw manifests with real values to Git — use <code>stringData</code> + sealed/external secret tooling, or SOPS-style encryption</li>\r\n<li>✅ Check your cluster: etcd encryption-at-rest is <b>opt-in</b> — many dev clusters run without it</li>\r\n</ul>\r\n<div class=\"cka\"><span class=\"ico\">🎓</span><div><b>Exam tip:</b> \"Are Secrets encrypted?\" — the honest answer is <b>\"encoded by default; encrypted only if etcd encryption-at-rest is configured.\"</b> Questions usually probe exactly this distinction.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch06\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch08\">next ▶</a></span><span>Page 9</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 08</span><h2 id=\"rbac-the-big-idea\">🪪 RBAC — The Big Idea</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<p>Authentication asks <b>\"who are you?\"</b> — authorization asks <b>\"may you do that?\"</b>. RBAC is Kubernetes' answer to the second question, and it's one grammatical sentence:</p>\r\n<div class=\"rowc\">\r\n<div class=\"kchip\">👤 WHO<small> User · Group · ServiceAccount</small></div>\r\n<span class=\"harr\">may</span>\r\n<div class=\"kchip\">🔨 VERB<small> get · list · watch · create · update · patch · delete</small></div>\r\n<span class=\"harr\">on</span>\r\n<div class=\"kchip\">🎯 RESOURCE<small> pods · secrets · deployments …</small></div>\r\n<span class=\"harr\">in</span>\r\n<div class=\"kchip\">🗂️ SCOPE<small> namespace or cluster</small></div>\r\n</div>\r\n<div class=\"grid2\">\r\n<div class=\"card\"><div class=\"zlabel\">The four objects</div>\r\n<div class=\"mtree\"><b>Role</b>            <span class=\"g\">rules, namespaced</span>\r\n<b>RoleBinding</b>      <span class=\"g\">attaches subjects → Role (ns)</span>\r\n<b>ClusterRole</b>      <span class=\"g\">rules, cluster-wide</span>\r\n<b>ClusterRoleBinding</b> <span class=\"g\">subjects → ClusterRole (all)</span></div></div>\r\n<div class=\"card\"><div class=\"zlabel\">Default posture</div>\r\n<p>Out of the box, RBAC grants regular users <b>nothing</b> — no Role = no access. Even the <b>default ServiceAccount</b> in each namespace has <b>zero API permissions</b> (a hardening choice since v1.22). Every capability is granted <i>explicitly</i>.</p>\r\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl auth can-i delete pods -n dev\r\n<span class=\"r\">no</span>  <span class=\"g\"># ← your first authorization question</span></div></div>\r\n</div>\r\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><code>kubectl auth can-i &lt;verb&gt; &lt;resource&gt; [-n ns]</code> is your constant companion — and with <code>--as=…</code> it answers for <i>other</i> identities (CH 09, Lab 3). Admins live in this command.</div></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Carry the sentence:</b> <i>Role = the rules · Binding = who gets them · Scope = where they apply.</i> Everything in the next three chapters is this sentence with different nouns.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch07\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch09\">next ▶</a></span><span>Page 10</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 09</span><h2 id=\"roles-amp-rolebindings\">📜 Roles &amp; RoleBindings</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<p>A <b>Role</b> is a namespaced rulebook; a <b>RoleBinding</b> hands that rulebook to people. Worked example — a CI bot that may read pods and manage config, nothing else:</p>\r\n<div class=\"term\"><span class=\"c\">apiVersion</span>: rbac.authorization.k8s.io/v1\r\n<span class=\"c\">kind</span>: Role\r\n<span class=\"c\">metadata</span>:\r\n  <span class=\"c\">name</span>: ci-reader\r\n  <span class=\"c\">namespace</span>: dev          <span class=\"g\"># Roles live IN a namespace</span>\r\n<span class=\"c\">rules</span>:\r\n- <span class=\"c\">apiGroups</span>: [<span class=\"m\">\"\"</span>]          <span class=\"g\"># \"\" = core group (pods, secrets…)</span>\r\n  <span class=\"c\">resources</span>: [<span class=\"m\">pods</span>, <span class=\"m\">pods/log</span>]\r\n  <span class=\"c\">verbs</span>: [<span class=\"m\">get</span>, <span class=\"m\">list</span>, <span class=\"m\">watch</span>]\r\n- <span class=\"c\">apiGroups</span>: [<span class=\"m\">\"\"</span>]\r\n  <span class=\"c\">resources</span>: [<span class=\"m\">configmaps</span>]\r\n  <span class=\"c\">verbs</span>: [<span class=\"m\">get</span>, <span class=\"m\">list</span>, <span class=\"m\">create</span>, <span class=\"m\">update</span>, <span class=\"m\">patch</span>]</div>\r\n<div class=\"term mini\"><span class=\"c\">kind</span>: RoleBinding\r\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: ci-reader-bind, <span class=\"c\">namespace</span>: dev }\r\n<span class=\"c\">roleRef</span>:\r\n  <span class=\"c\">apiGroup</span>: rbac.authorization.k8s.io\r\n  <span class=\"c\">kind</span>: Role\r\n  <span class=\"c\">name</span>: ci-reader            <span class=\"g\"># the rulebook</span>\r\n<span class=\"c\">subjects</span>:                    <span class=\"g\"># WHO receives it</span>\r\n- <span class=\"c\">kind</span>: ServiceAccount\r\n  <span class=\"c\">name</span>: ci-bot\r\n  <span class=\"c\">namespace</span>: dev</div>\r\n<div class=\"term mini\"><span class=\"g\"># verify — answer FOR the bot without being the bot:</span>\r\n<span class=\"p\">$</span> kubectl auth can-i list pods -n dev \\\r\n    <span class=\"y\">--as</span>=system:serviceaccount:dev:ci-bot\r\n<span class=\"p\">yes</span>\r\n<span class=\"p\">$</span> kubectl auth can-i delete pods -n dev \\\r\n    <span class=\"y\">--as</span>=system:serviceaccount:dev:ci-bot\r\n<span class=\"r\">no</span>  <span class=\"g\"># not in the rulebook → denied</span></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Bindings are the only on-switch.</b> Creating a Role changes nothing by itself; access exists only when a Binding names a subject. And verbs are literal — <code>list</code> does not imply <code>delete</code>.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch08\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch10\">next ▶</a></span><span>Page 11</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 10</span><h2 id=\"clusterroles-amp-when-to-use-which\">🌐 ClusterRoles &amp; When to Use Which</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<p>A <b>ClusterRole</b> is a rulebook that isn't tied to a namespace. Pairing it with the right binding type decides its reach:</p>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Pairing</th><th>Effective scope</th><th>Use when…</th></tr>\r\n<tr><td><b>Role + RoleBinding</b></td><td>one namespace</td><td>team/app permissions (the 90% case)</td></tr>\r\n<tr><td><b>ClusterRole + RoleBinding</b></td><td><b>one namespace</b> per binding</td><td>reuse one rulebook in many namespaces — bind the <i>same</i> ClusterRole to <code>dev</code>, <code>qa</code>, <code>prod</code> teams separately</td></tr>\r\n<tr><td><b>ClusterRole + ClusterRoleBinding</b></td><td>entire cluster</td><td>platform admins, controllers that watch everything</td></tr>\r\n<tr><td><s>Role + ClusterRoleBinding</s></td><td><span class=\"bad\">❌ impossible</span> — a cluster-wide binding can't reference a namespaced Role</td></tr>\r\n</table></div>\r\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The classic trap:</b> some resources are <b>cluster-scoped</b> (Book 01 · CH 11): <i>Nodes, PersistentVolumes, Namespaces, ClusterRoles</i>. They <b>cannot</b> be governed by a namespaced Role — you must use a <b>ClusterRole</b>, even if you only want narrow access to, say, Nodes.</div></div>\r\n<div class=\"term mini\"><span class=\"g\"># \"let the monitoring bot READ nodes\" — needs ClusterRole:</span>\r\n<span class=\"c\">kind</span>: ClusterRole\r\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: node-reader }   <span class=\"g\"># note: no namespace field</span>\r\n<span class=\"c\">rules</span>:\r\n- <span class=\"c\">apiGroups</span>: [<span class=\"m\">\"\"</span>]\r\n  <span class=\"c\">resources</span>: [<span class=\"m\">nodes</span>]\r\n  <span class=\"c\">verbs</span>: [<span class=\"m\">get</span>, <span class=\"m\">list</span>, <span class=\"m\">watch</span>]</div>\r\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Why ClusterRole + RoleBinding is the pro move:</b> one canonical rulebook (audited once), namespace-scoped blast radius per binding. ClusterRoleBinding is a big hammer — reserve it for identities that truly need the whole cluster.</div></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Decision in one line:</b> start with <b>Role + RoleBinding</b>; graduate to <b>ClusterRole + RoleBinding</b> for reuse; <b>ClusterRoleBinding</b> only for genuinely cluster-wide identities — and remember cluster-scoped resources <i>force</i> a ClusterRole.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch09\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch11\">next ▶</a></span><span>Page 12</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 11</span><h2 id=\"serviceaccounts\">👷 ServiceAccounts</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<p>Users are for <b>people</b>; a <b>ServiceAccount (SA)</b> is an identity for <b>workloads</b> — the \"staff badge\" your Pod wears when it talks to the API Server.</p>\r\n<ul>\r\n<li>🏷️ Every namespace ships a <code>default</code> SA — Pods without an explicit <code>serviceAccountName</code> wear it</li>\r\n<li>🎫 A Pod's SA gets a <b>projected token</b> mounted at <code>/var/run/secrets/kubernetes.io/serviceaccount</code> — that's the credential the app's k8s client uses (auto-discovered in-cluster)</li>\r\n<li>🚫 Modern RBAC gives the default SA <b>no permissions</b> — a Pod that doesn't call the API should opt out:</li>\r\n</ul>\r\n<div class=\"term\"><span class=\"c\">spec</span>:\r\n  <span class=\"c\">serviceAccountName</span>: ci-bot      <span class=\"g\"># wear THIS badge</span>\r\n  <span class=\"c\">automountServiceAccountToken</span>: <span class=\"y\">false</span>  <span class=\"g\"># …or wear none</span></div>\r\n<h3 id=\"the-full-chain-badge-rulebook\">🔗 The full chain — badge → rulebook</h3>\r\n<div class=\"mtree\"><b>Pod</b> wears <u>ServiceAccount ci-bot</u>\r\n        │\r\n        └── <b>RoleBinding</b> grants <em>ci-reader</em> Role <span class=\"g\">(CH 09)</span>\r\n                │\r\n                └── result: <u>list pods ✓</u> · <s>delete pods ✗</s> <span class=\"g\">in ns dev only</span></div>\r\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl create serviceaccount ci-bot -n dev\r\n<span class=\"p\">$</span> kubectl set serviceaccount deploy/web ci-bot -n dev\r\n<span class=\"p\">$</span> kubectl auth can-i get secrets -n dev \\\r\n    <span class=\"y\">--as</span>=system:serviceaccount:dev:ci-bot\r\n<span class=\"r\">no</span>  <span class=\"g\"># ← this is what a stolen Pod token can do. audit it.</span></div>\r\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The Pod-token threat model:</b> anyone who can <code>exec</code> into your Pod can read its token and <b>become</b> that SA. Scope each SA's Role to the minimum (Lab 3 audits exactly this) — never run untrusted workloads under an admin-bound SA.</div></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> <i>ServiceAccount = workload identity; RoleBinding = its permissions; the mounted token = its key.</i> RBAC + SAs together answer \"what damage can this Pod do?\"</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch10\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch12\">next ▶</a></span><span>Page 13</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 12</span><h2 id=\"securitycontext\">🛡️ SecurityContext</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<p>RBAC governs your Pod's <i>API</i> permissions; the SecurityContext governs its <i>Linux</i> permissions. Two levels apply:</p>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Level</th><th>Fields</th><th>Notes</th></tr>\r\n<tr><td><b>Pod-level</b> <code>spec.securityContext</code></td><td><code>runAsUser</code> · <code>runAsGroup</code> · <code>runAsNonRoot</code> · <code>fsGroup</code></td><td>defaults inherited by every container</td></tr>\r\n<tr><td><b>Container-level</b> <code>containers[].securityContext</code></td><td>all of the above <b>+</b> <code>readOnlyRootFilesystem</code> · <code>allowPrivilegeEscalation</code> · <code>capabilities</code> · <code>privileged</code></td><td>overrides pod-level per container</td></tr>\r\n</table></div>\r\n<div class=\"term\"><span class=\"c\">spec</span>:\r\n  <span class=\"c\">securityContext</span>:            <span class=\"g\"># POD level</span>\r\n    <span class=\"c\">runAsNonRoot</span>: <span class=\"y\">true</span>        <span class=\"g\"># refuse to start as uid 0</span>\r\n    <span class=\"c\">runAsUser</span>: <span class=\"y\">1000</span>\r\n    <span class=\"c\">fsGroup</span>: <span class=\"y\">2000</span>             <span class=\"g\"># group ownership for volumes</span>\r\n  <span class=\"c\">containers</span>:\r\n  - <span class=\"c\">name</span>: app\r\n    <span class=\"c\">image</span>: myapp:2.0\r\n    <span class=\"c\">securityContext</span>:          <span class=\"g\"># CONTAINER level</span>\r\n      <span class=\"c\">readOnlyRootFilesystem</span>: <span class=\"y\">true</span>   <span class=\"g\"># tamper-proof image FS</span>\r\n      <span class=\"c\">allowPrivilegeEscalation</span>: <span class=\"y\">false</span>\r\n      <span class=\"c\">capabilities</span>:\r\n        <span class=\"c\">drop</span>: [<span class=\"m\">\"ALL\"</span>]         <span class=\"g\"># shed Linux superpowers</span></div>\r\n<ul>\r\n<li>🧱 <code>readOnlyRootFilesystem</code> → writes must go to mounted <code>emptyDir</code> volumes — a common first hardening step</li>\r\n<li>🚫 <code>privileged: true</code> ≈ root on the node — <b>never</b> for untrusted workloads (PSS · CH 13 forbids it outright at Baseline+)</li>\r\n</ul>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Remember the pairing:</b> <b>RBAC = may it call the API?</b> · <b>SecurityContext = what can it do to the machine?</b> Book 01's CH 07 taint story protected the node from scheduling; this protects the node from the container.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch11\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch13\">next ▶</a></span><span>Page 14</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 13</span><h2 id=\"pod-security-standards\">🚨 Pod Security Standards</h2><span class=\"dbadge\">🟢 5 MIN</span></div>\r\n<p>Checking every Pod's SecurityContext by hand doesn't scale. <b>Pod Security Standards (PSS)</b> define three ready-made security levels, enforced cluster-wide by namespace labels.</p>\r\n<div class=\"grid3\">\r\n<div class=\"card center\"><div>🔓</div><p><b>Privileged</b><br />no restrictions — trusted, cluster-infrastructure workloads only</p></div>\r\n<div class=\"card center\"><div>🔒</div><p><b>Baseline</b><br />blocks the obviously dangerous (hostNetwork, privileged:true) while allowing common apps</p></div>\r\n<div class=\"card center\"><div>🔐</div><p><b>Restricted</b><br />current hardening best practice: runAsNonRoot, drop ALL capabilities, no privilege escalation</p></div>\r\n</div>\r\n<div class=\"term mini\"><span class=\"g\"># enforce on a namespace — three modes per level:</span>\r\n<span class=\"p\">$</span> kubectl label ns prod \\\r\n  <span class=\"y\">pod-security.kubernetes.io/enforce</span>=restricted \\\r\n  <span class=\"y\">pod-security.kubernetes.io/audit</span>=restricted \\\r\n  <span class=\"y\">pod-security.kubernetes.io/warn</span>=restricted</div>\r\n<ul>\r\n<li>🚧 <b>enforce</b> — rejecting non-compliant Pods · 🔍 <b>audit</b> — log violations · ⚠️ <b>warn</b> — message the user</li>\r\n<li>🪜 Migration pattern: run <code>warn+audit</code> first, fix offenders, then switch on <code>enforce</code></li>\r\n</ul>\r\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Version note:</b> the old <b>PodSecurityPolicy (PSP)</b> was removed in Kubernetes <b>v1.25</b>. If a tutorial teaches PSP, it's stale — the modern mechanism is <b>PSS via Pod Security Admission</b> (the labels above).</div></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One line:</b> <i>PSS = cluster policy, three levels (Privileged → Baseline → Restricted), applied per-namespace with enforce/audit/warn labels.</i> \"Restricted\" ≈ your CH 12 SecurityContext, made mandatory.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch12\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch14\">next ▶</a></span><span>Page 15</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 14</span><h2 id=\"requests-amp-limits\">📊 Requests &amp; Limits</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\r\n<div class=\"grid2\">\r\n<div class=\"card\">\r\n<h3 id=\"requests-the-promise\">REQUESTS — the promise</h3>\r\n<p>What the container is <b>guaranteed</b>. The <b>Scheduler</b> places Pods only on Nodes with enough <i>requestable</i> capacity (Book 01 · CH 06's \"Pending\" mystery starts here).</p></div>\r\n<div class=\"card\">\r\n<h3 id=\"limits-the-ceiling\">LIMITS — the ceiling</h3>\r\n<p>The maximum the runtime <b>enforces</b>. What happens at the ceiling <b>differs radically by resource type</b> — the table below is the exam's favorite nuance.</p></div>\r\n</div>\r\n<div class=\"term\"><span class=\"c\">containers</span>:\r\n- <span class=\"c\">name</span>: app\r\n  <span class=\"c\">image</span>: myapp:2.0\r\n  <span class=\"c\">resources</span>:\r\n    <span class=\"c\">requests</span>: { <span class=\"c\">cpu</span>: <span class=\"m\">\"250m\"</span>, <span class=\"c\">memory</span>: <span class=\"y\">\"256Mi\"</span> }\r\n    <span class=\"c\">limits</span>:   { <span class=\"c\">cpu</span>: <span class=\"m\">\"500m\"</span>, <span class=\"c\">memory</span>: <span class=\"y\">\"512Mi\"</span> }</div>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Resource</th><th>Exceeding the limit →</th><th>Feels like</th></tr>\r\n<tr><td><b>CPU</b> (compressible)</td><td><span class=\"stbadge st-pend\">Throttled</span> — process slowed via CFS quota</td><td>sluggish app, elevated latency, <b>no restart</b></td></tr>\r\n<tr><td><b>Memory</b> (incompressible)</td><td><span class=\"stbadge st-term\">OOMKilled</span> — SIGKILL, exit code <b>137</b></td><td>container dies; RestartPolicy kicks in → often CrashLoopBackOff</td></tr>\r\n</table></div>\r\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl describe pod oom-demo | <span class=\"c\">grep</span> -A3 Last State\r\n<span class=\"y\">   Last State:     Terminated</span>\r\n<span class=\"r\">     Reason:       OOMKilled</span>\r\n<span class=\"r\">     Exit Code:    137</span>  <span class=\"g\"># = 128 + 9 (SIGKILL)</span></div>\r\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The overcommit trap:</b> total requests &lt; node capacity &lt; total limits is legal and common — the cluster <i>borrows</i> headroom. When a node runs out of <i>real</i> memory, the kube evicts by QoS class — which is exactly CH 15.</div></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Memory hook:</b> CPU over limit = <b>tickets get slower</b> · memory over limit = <b>you're escorted out (137)</b>. CPU can be shared; memory cannot be un-consumed.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch13\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch15\">next ▶</a></span><span>Page 16</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 15</span><h2 id=\"qos-classes\">🎚️ QoS Classes</h2><span class=\"dbadge\">🟡 5 MIN · CORE</span></div>\r\n<p>Every Pod is silently stamped with a Quality-of-Security— sorry, Quality-of-<b>Service</b> class, derived <b>purely from its requests/limits</b>. It decides who gets evicted first when a node runs dry.</p>\r\n<div class=\"mtree\"><b>Guaranteed</b>  every container: <u>requests == limits</u> for <i>both</i> cpu AND memory\r\n<b>Burstable</b>   at least ONE requests/limits field set (anything else)\r\n<b>BestEffort</b>  no requests, no limits — anything</div>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Class</th><th>Derivation</th><th>Eviction order under node pressure</th></tr>\r\n<tr><td><span class=\"stbadge st-run\">Guaranteed</span></td><td>requests == limits (all containers)</td><td><b>last</b> — killed only after others</td></tr>\r\n<tr><td><span class=\"stbadge st-pend\">Burstable</span></td><td>some resources specified</td><td>middle — those <b>exceeding requests</b> go first</td></tr>\r\n<tr><td><span class=\"stbadge st-term\">BestEffort</span></td><td>nothing specified</td><td><b>first</b> — zero promises, zero protection</td></tr>\r\n</table></div>\r\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl get pod web -o jsonpath=<span class=\"m\">'{.status.qosClass}'</span>\r\nBurstable</div>\r\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Why this matters operationally:</b> your database should be <b>Guaranteed</b> (it's the thing you least want killed); dev/experiment Pods can ride <b>BestEffort</b> as the cluster's shock absorber. QoS is how Kubernetes turns your YAML honesty into survival priority.</div></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The chain, end to end:</b> requests → where the Scheduler may place you · limits → what happens when you misbehave · QoS → who survives when the node itself starves. Part V now proves all of it hands-on.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch14\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab1\">labs ▶</a></span><span>Page 17</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 1</span><h2 id=\"configmap-prove-env-hot-reload\">🔬 ConfigMap — Prove Env ≠ Hot-Reload</h2><span class=\"dbadge\">🟠 12 MIN · HANDS-ON</span></div>\r\n<div class=\"labstep\"><div>STEP 1 · One ConfigMap, both consumption methods</div>\r\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl create configmap demo <span class=\"y\">--from-literal</span>=GREETING=hello\r\n<span class=\"p\">$</span> kubectl run cfg-demo --image=busybox --restart=Never \\\r\n  --overrides=<span class=\"m\">'{\"spec\":{\"containers\":[{\"name\":\"c\",\"image\":\"busybox\",\r\n  \"command\":[\"sh\",\"-c\",\"sleep 9999\"],\r\n  \"env\":[{\"name\":\"GREETING\",\"valueFrom\":{\"configMapKeyRef\":{\"name\":\"demo\",\"key\":\"GREETING\"}}}],\r\n  \"volumeMounts\":[{\"name\":\"cfg\",\"mountPath\":\"/etc/cfg\"}]}],\r\n  \"volumes\":[{\"name\":\"cfg\",\"configMap\":{\"name\":\"demo\"}}]}}'</span></div></div>\r\n<div class=\"grid2\">\r\n<div class=\"tabwin\"><div class=\"tabhead\">👀 TAB 1 · OBSERVE</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl exec cfg-demo -- <span class=\"c\">printenv</span> GREETING\r\nhello\r\n<span class=\"p\">$</span> kubectl exec cfg-demo -- <span class=\"c\">cat</span> /etc/cfg/GREETING\r\nhello</div></div>\r\n<div class=\"tabwin\"><div class=\"tabhead\">⚙️ TAB 2 · CHANGE IT</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl patch cm demo <span class=\"y\">-p</span> \\\r\n  <span class=\"m\">'{\"data\":{\"GREETING\":\"howdy\"}}'</span>\r\nconfigmap/demo patched</div></div>\r\n</div>\r\n<div class=\"labstep\"><div>STEP 2 · Wait ~1 min, re-check</div>\r\n<div class=\"labcols\">\r\n<div><div class=\"labtag\">👀 ENV VAR — the snapshot</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl exec cfg-demo -- <span class=\"c\">printenv</span> GREETING\r\n<span class=\"r\">hello</span>  <span class=\"g\"># ← UNCHANGED, forever</span></div></div>\r\n<div><div class=\"labtag\">👀 VOLUME FILE — the live feed</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl exec cfg-demo -- <span class=\"c\">cat</span> /etc/cfg/GREETING\r\n<span class=\"p\">howdy</span>  <span class=\"g\"># ← updated by kubelet (~1 min)</span></div></div>\r\n</div>\r\n<p><b>Proved:</b> the matrix from CH 03 is real — env is a boot-time snapshot; volume mounts are kubelet-synced. <b>Teardown:</b> <code>kubectl delete pod cfg-demo &amp;&amp; kubectl delete cm demo</code>.</p></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#ch15\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab2\">next ▶</a></span><span>Page 18</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 2</span><h2 id=\"secret-encoded-not-encrypted\">🔐 Secret — Encoded, Not Encrypted</h2><span class=\"dbadge\">🟠 8 MIN · HANDS-ON</span></div>\r\n<div class=\"labstep\"><div>STEP 1 · Create, mount, go inside</div>\r\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl create secret generic lab-sec <span class=\"y\">--from-literal</span>=PASSWORD=<span class=\"m\">\"hunter2\"</span>\r\n<span class=\"p\">$</span> kubectl run sec-demo --image=busybox --restart=Never \\\r\n  --overrides=<span class=\"m\">'{\"spec\":{\"containers\":[{\"name\":\"c\",\"image\":\"busybox\",\r\n  \"command\":[\"sh\",\"-c\",\"sleep 9999\"],\r\n  \"volumeMounts\":[{\"name\":\"s\",\"mountPath\":\"/etc/sec\",\"readOnly\":true}]}],\r\n  \"volumes\":[{\"name\":\"s\",\"secret\":{\"secretName\":\"lab-sec\"}}]}}'</span></div></div>\r\n<div class=\"labstep\"><div>STEP 2 · Read the \"hidden\" value — three levels of nakedness</div>\r\n<div class=\"term mini\"><span class=\"g\"># inside the pod — the file is ALREADY DECODED for the app:</span>\r\n<span class=\"p\">$</span> kubectl exec sec-demo -- <span class=\"c\">cat</span> /etc/sec/PASSWORD\r\n<span class=\"p\">hunter2</span>\r\n<span class=\"g\"># from the API — only base64 stands in the way:</span>\r\n<span class=\"p\">$</span> kubectl get secret lab-sec -o jsonpath=<span class=\"m\">'{.data.PASSWORD}'</span>\r\n<span class=\"y\">aHVudGVyMg==</span>\r\n<span class=\"p\">$</span> <span class=\"c\">echo</span> aHVudGVyMg== | <span class=\"c\">base64</span> <span class=\"y\">-d</span>  <span class=\"g\"># → hunter2. instantly.</span></div>\r\n<p><b>Proved:</b> CH 07's claim — base64 protects nothing; the kubelet even hands your app the decoded value. Protection lives in <b>who may run <code>get secret</code></b> (RBAC) and etcd encryption-at-rest. <b>Teardown:</b> <code>kubectl delete pod sec-demo &amp;&amp; kubectl delete secret lab-sec</code>.</p></div>\r\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Interview one-liner born from this lab:</b> \"Secrets protect against <i>casual exposure</i> and unauthenticated reads — not against anyone holding <code>get secrets</code> RBAC.\"</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#lab1\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab3\">next ▶</a></span><span>Page 19</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 3</span><h2 id=\"rbac-can-i-as-a-serviceaccount\">🪪 RBAC — Can-I as a ServiceAccount</h2><span class=\"dbadge\">🟠 12 MIN · HANDS-ON</span></div>\r\n<div class=\"labstep\"><div>STEP 1 · Build the chain: SA → Role → Binding</div>\r\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl create ns rbac-lab\r\n<span class=\"p\">$</span> kubectl create serviceaccount bot -n rbac-lab\r\n<span class=\"p\">$</span> kubectl create role podlist <span class=\"y\">--verb</span>=get,list <span class=\"y\">--resource</span>=pods -n rbac-lab\r\n<span class=\"p\">$</span> kubectl create rolebinding bot-bind <span class=\"y\">--role</span>=podlist \\\r\n    <span class=\"y\">--serviceaccount</span>=rbac-lab:bot -n rbac-lab</div></div>\r\n<div class=\"labstep\"><div>STEP 2 · Interrogate the bot's permissions</div>\r\n<div class=\"term mini\"><span class=\"p\">$</span> <span class=\"c\">K=\"--as=system:serviceaccount:rbac-lab:bot -n rbac-lab\"</span>\r\n<span class=\"p\">$</span> kubectl auth <span class=\"c\">can-i</span> list pods    $K     <span class=\"g\"># in the rulebook</span>\r\n<span class=\"p\">yes</span>\r\n<span class=\"p\">$</span> kubectl auth <span class=\"c\">can-i</span> delete pods  $K     <span class=\"g\"># verbs are literal!</span>\r\n<span class=\"r\">no</span>\r\n<span class=\"p\">$</span> kubectl auth <span class=\"c\">can-i</span> list secrets $K     <span class=\"g\"># resources too</span>\r\n<span class=\"r\">no</span>\r\n<span class=\"p\">$</span> kubectl auth <span class=\"c\">can-i</span> list pods -n default $K <span class=\"g\"># scope is namespaced!</span>\r\n<span class=\"r\">no</span></div></div>\r\n<div class=\"labstep\"><div>STEP 3 · What we proved</div>\r\n<ul>\r\n<li>✅ The bot may <b>list pods</b> — exactly one namespace, exactly the granted verbs</li>\r\n<li>❌ Delete? Secrets? Other namespaces? All <b>no</b> — default posture is deny; the Role's scope is absolute</li>\r\n<li>🔎 <code>--as</code> lets you <b>audit any identity without their credentials</b> — the core of RBAC troubleshooting</li>\r\n</ul>\r\n<p><b>Teardown:</b> <code>kubectl delete ns rbac-lab</code> — the cascade (Book 01 · Lab 3) removes the whole chain.</p></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#lab2\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab4\">next ▶</a></span><span>Page 20</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 4</span><h2 id=\"trigger-an-oomkill-on-purpose\">💥 Trigger an OOMKill on Purpose</h2><span class=\"dbadge\">🟠 10 MIN · HANDS-ON</span></div>\r\n<div class=\"labstep\"><div>STEP 1 · Deploy a Pod with a tiny memory limit and a big appetite</div>\r\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl set image deploy/oom-demo oom=polinux/stress \\\r\n  -n default 2&gt;/dev/null || kubectl create deploy oom-demo --image=polinux/stress \\\r\n  -- stress --vm 1 --vm-bytes 200M --timeout 300s\r\n<span class=\"p\">$</span> kubectl set resources deploy/oom-demo <span class=\"y\">--limits</span>=memory=<span class=\"r\">50Mi</span> <span class=\"y\">--requests</span>=memory=30Mi\r\n<span class=\"p\">$</span> kubectl get pods -w</div></div>\r\n<div class=\"grid2\">\r\n<div class=\"tabwin\"><div class=\"tabhead\">👀 TAB 1 · WATCH</div><div class=\"tabbody\"><span class=\"y\">NAME             STATUS   RESTARTS</span>\r\noom-demo-<span class=\"c\">aaaaa</span>  <span class=\"p\">Running</span>  0\r\noom-demo-aaaaa  <span class=\"r\">Error</span>     1  <span class=\"g\"># OOM!</span>\r\noom-demo-aaaaa  <span class=\"p\">Running</span>  1\r\noom-demo-aaaaa  <span class=\"r\">Error</span>     2  <span class=\"g\"># again…</span></div></div>\r\n<div class=\"tabwin\"><div class=\"tabhead\">🔍 TAB 2 · AUTOPSY</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl describe pod -l app=oom-demo\r\n  <span class=\"y\">Last State: Terminated</span>\r\n<span class=\"r\">    Reason:   OOMKilled</span>\r\n<span class=\"r\">    Exit:     137</span>\r\n<span class=\"g\"># 128+9 = SIGKILL by the\r\n# kernel's OOM killer</span></div></div>\r\n</div>\r\n<div class=\"labstep\"><div>STEP 2 · What we proved</div>\r\n<ul>\r\n<li>✅ Memory limit exceeded → <b>OOMKilled (137)</b>, not throttled — CH 14's incompressible-resource rule</li>\r\n<li>✅ The Deployment's reconciliation (Book 01 · CH 06) restarts it → it OOMs again → the classic <b>CrashLoopBackOff</b> signature</li>\r\n<li>🩺 Real-world translation: <i>app that crash-loops right after startup + exit 137 = raise the limit or fix the leak</i></li>\r\n</ul>\r\n<p><b>Teardown:</b> <code>kubectl delete deploy oom-demo</code>. (Then check its QoS: it had requests≠limits → <code>Burstable</code> — CH 15 in the flesh.)</p></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#lab3\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#quiz\">quiz ▶</a></span><span>Page 21</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">QUIZ</span><h2 id=\"self-check-quiz\">✅ Self-Check Quiz</h2><span class=\"dbadge\">☑ 10 questions</span></div>\r\n<div class=\"qz\"><span class=\"qn\">Q1.</span>A ConfigMap is consumed by a Pod both as an env var and as a volume file. You update the ConfigMap. What does the running Pod see?<br /><b>A.</b> Both update within ~1 min   <b>B.</b> Env unchanged; the volume file updates eventually   <b>C.</b> Env updates; file unchanged   <b>D.</b> Neither — a restart is always required</div>\r\n<div class=\"qz\"><span class=\"qn\">Q2.</span>A colleague says Secrets are \"encrypted by Kubernetes\". The accurate response?<br /><b>A.</b> True — always encrypted in etcd   <b>B.</b> True, but only for Opaque type   <b>C.</b> False — values are base64-<i>encoded</i>; encryption-at-rest must be explicitly enabled   <b>D.</b> False — Secrets are stored in plain text in the API Server's memory</div>\r\n<div class=\"qz\"><span class=\"qn\">Q3.</span>Which Secret type must contain the key <code>.dockerconfigjson</code>?<br /><b>A.</b> Opaque   <b>B.</b> kubernetes.io/tls   <b>C.</b> kubernetes.io/dockerconfigjson   <b>D.</b> basic-auth</div>\r\n<div class=\"qz\"><span class=\"qn\">Q4.</span>By default, which identity may read Secrets in namespace <code>dev</code>?<br /><b>A.</b> Any authenticated user   <b>B.</b> The default ServiceAccount   <b>C.</b> Cluster admins only, forever   <b>D.</b> Nobody beyond cluster-admin-tier until an RBAC Role/Binding grants it</div>\r\n<div class=\"qz\"><span class=\"qn\">Q5.</span><code>kubectl auth can-i get pods --as=system:serviceaccount:dev:bot</code> answers…<br /><b>A.</b> Can the bot authenticate?   <b>B.</b> May <i>bot</i> perform <i>get pods</i>? (authorization, impersonated)   <b>C.</b> Do you have permission?   <b>D.</b> Does the Role exist?</div>\r\n<div class=\"qz\"><span class=\"qn\">Q6.</span>A RoleBinding may reference which rulebook(s)?<br /><b>A.</b> Role only   <b>B.</b> ClusterRole only   <b>C.</b> Role or ClusterRole   <b>D.</b> Neither — bindings only reference users</div>\r\n<div class=\"qz\"><span class=\"qn\">Q7.</span>A Pod is classed <b>Guaranteed</b> when…<br /><b>A.</b> It runs on 3+ nodes   <b>B.</b> limits only are set   <b>C.</b> Every container sets requests == limits for both CPU and memory   <b>D.</b> It has priorityClassName set</div>\r\n<div class=\"qz\"><span class=\"qn\">Q8.</span>A container consistently exceeds its memory limit. Result?<br /><b>A.</b> CPU throttling   <b>B.</b> Pod rescheduled   <b>C.</b> Limit auto-raised   <b>D.</b> OOMKilled — exit code 137</div>\r\n<div class=\"qz\"><span class=\"qn\">Q9.</span><code>readOnlyRootFilesystem</code> is set at which level?<br /><b>A.</b> Namespace   <b>B.</b> Role   <b>C.</b> Container securityContext   <b>D.</b> ServiceAccount</div>\r\n<div class=\"qz\"><span class=\"qn\">Q10.</span>Which PSS level requires runAsNonRoot, dropping ALL capabilities, and disabling privilege escalation?<br /><b>A.</b> Privileged   <b>B.</b> Restricted   <b>C.</b> Baseline   <b>D.</b> PodSecurityPolicy</div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#lab4\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#key\">answers ▶</a></span><span>Page 22</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">KEY</span><h2 id=\"answer-key-scoring\">🗝️ Answer Key + Scoring</h2><span class=\"dbadge\">grade yourself</span></div>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Q</th><th>Ans</th><th>Why — one line</th></tr>\r\n<tr><td>1</td><td><b>B</b></td><td>Env = boot snapshot, never updates; volume files kubelet-synced ~1 min — CH 02/03</td></tr>\r\n<tr><td>2</td><td><b>C</b></td><td>Base64 is transport encoding; etcd encryption-at-rest is opt-in — CH 07</td></tr>\r\n<tr><td>3</td><td><b>C</b></td><td>dockerconfigjson type mandates the <code>.dockerconfigjson</code> key — CH 05/06</td></tr>\r\n<tr><td>4</td><td><b>D</b></td><td>Default posture is deny; even the default SA has zero permissions — CH 08/11</td></tr>\r\n<tr><td>5</td><td><b>B</b></td><td>can-i + <code>--as</code> = authorization check for an impersonated identity — CH 08/09</td></tr>\r\n<tr><td>6</td><td><b>C</b></td><td>RoleBinding may bind a ClusterRole, scoping it to its namespace — CH 10</td></tr>\r\n<tr><td>7</td><td><b>C</b></td><td>Guaranteed = requests==limits, cpu AND memory, every container — CH 15</td></tr>\r\n<tr><td>8</td><td><b>D</b></td><td>Memory is incompressible → OOMKill, 128+9=137 — CH 14, Lab 4</td></tr>\r\n<tr><td>9</td><td><b>C</b></td><td>readOnlyRootFilesystem is container-level SecurityContext — CH 12</td></tr>\r\n<tr><td>10</td><td><b>B</b></td><td>Restricted = hardening best practice; PSP is removed (v1.25) — CH 13</td></tr>\r\n</table></div>\r\n<div class=\"grid3\">\r\n<div class=\"card center\"><div>🏆</div><p><b>9–10</b><br />Ready for Book 03</p></div>\r\n<div class=\"card center\"><div>📖</div><p><b>6–8</b><br />Re-read the missed chapters' 🔑 boxes</p></div>\r\n<div class=\"card center\"><div>🔁</div><p><b>&lt;6</b><br />Re-run Labs 1–4, then retake</p></div>\r\n</div>\r\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Missed Q2 or Q4?</b> Those are the two real-world security gaps — \"encoded ≠ encrypted\" and \"default deny\". Missed Q6? The ClusterRole+RoleBinding combo is the most misremembered fact in RBAC.</div></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#quiz\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#gloss\">next ▶</a></span><span>Page 23</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">GLOSS</span><h2 id=\"glossary\">📚 Glossary</h2><span class=\"dbadge\">🔵 REFERENCE</span></div>\r\n<div class=\"gl\"><b>ConfigMap</b> — namespaced key/value (or file) store for plain config; consumed as env vars or volume files.</div>\r\n<div class=\"gl\"><b>Hot-reload</b> — volume-mounted ConfigMaps/Secrets update automatically (~1 min, eventual); env vars and subPath mounts never do.</div>\r\n<div class=\"gl\"><b>Secret</b> — ConfigMap's sensitive sibling; base64-encoded values, RBAC-gated reads, same two consumption methods.</div>\r\n<div class=\"gl\"><b>Opaque</b> — default Secret type: arbitrary key/value pairs.</div>\r\n<div class=\"gl\"><b>imagePullSecrets</b> — registry credentials used by the kubelet to pull private images; best attached at ServiceAccount level.</div>\r\n<div class=\"gl\"><b>Base64</b> — transport encoding, not encryption. Decodable by anyone in one command.</div>\r\n<div class=\"gl\"><b>Encryption at rest</b> — opt-in kube-apiserver EncryptionConfiguration that encrypts Secrets inside etcd.</div>\r\n<div class=\"gl\"><b>Authentication vs Authorization</b> — who are you vs may you do that. RBAC answers the second.</div>\r\n<div class=\"gl\"><b>Role / ClusterRole</b> — namespaced / cluster-level rulebooks: verbs on resources.</div>\r\n<div class=\"gl\"><b>RoleBinding / ClusterRoleBinding</b> — attach subjects to rulebooks; a RoleBinding may bind a ClusterRole but scope it to its namespace.</div>\r\n<div class=\"gl\"><b>Subject</b> — User, Group, or ServiceAccount named by a Binding.</div>\r\n<div class=\"gl\"><b>ServiceAccount</b> — workload identity; its projected token (mounted in the Pod) is the credential Pods use against the API.</div>\r\n<div class=\"gl\"><b>SecurityContext</b> — Linux-level hardening: runAsNonRoot, readOnlyRootFilesystem, capabilities, allowPrivilegeEscalation (pod- and container-level).</div>\r\n<div class=\"gl\"><b>Pod Security Standards</b> — Privileged / Baseline / Restricted levels enforced per-namespace via pod-security.kubernetes.io labels (successor to removed PSP).</div>\r\n<div class=\"gl\"><b>Requests / Limits</b> — guaranteed capacity for scheduling / enforced ceiling (CPU throttles; memory OOMKills with exit 137).</div>\r\n<div class=\"gl\"><b>QoS Class</b> — Guaranteed (req==lim) · Burstable (partial) · BestEffort (none) — determines eviction order under node pressure.</div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#key\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#cheat\">next ▶</a></span><span>Page 24</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CHEAT</span><h2 id=\"one-page-cheat-sheet\">📄 One-Page Cheat Sheet</h2><span class=\"dbadge\">🔵 print me</span></div>\r\n<div class=\"grid2\">\r\n<div class=\"card\"><div class=\"zlabel\">⚙️ Config &amp; Secrets — commands</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl create configmap cm --from-literal=K=V --from-file=f.conf\r\n<span class=\"p\">$</span> kubectl create secret generic s --from-literal=K=V\r\n<span class=\"p\">$</span> kubectl create secret docker-registry reg --docker-server=… --docker-username=…\r\n<span class=\"p\">$</span> kubectl create secret tls t --cert=crt --key=key\r\n<span class=\"p\">$</span> kubectl get secret s -o jsonpath='{.data.K}' | base64 -d\r\n<span class=\"p\">$</span> kubectl patch sa default -p '{\"imagePullSecrets\":[{\"name\":\"reg\"}]}'</div></div>\r\n<div class=\"card\"><div class=\"zlabel\">🪪 RBAC — commands</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl create role r --verb=get,list --resource=pods -n ns\r\n<span class=\"p\">$</span> kubectl create rolebinding rb --role=r --serviceaccount=ns:sa -n ns\r\n<span class=\"p\">$</span> kubectl create clusterrole cr --verb=get --resource=nodes\r\n<span class=\"p\">$</span> kubectl auth can-i delete pods -n ns --as=system:serviceaccount:ns:sa\r\n<span class=\"p\">$</span> kubectl describe role/rolebinding …  <span class=\"g\"># audit what exists</span></div></div>\r\n</div>\r\n<div class=\"grid2\">\r\n<div class=\"card\"><div class=\"zlabel\">🔄 Hot-reload matrix</div><div class=\"table-scroll\"><table><tr><th>Consumed as</th><th>Updates?</th></tr><tr><td>env var</td><td><span class=\"bad\">never</span></td></tr><tr><td>volume file</td><td><span class=\"ok\">yes (~1 min)</span></td></tr><tr><td>subPath mount</td><td><span class=\"bad\">never</span></td></tr></table></div></div>\r\n<div class=\"card\"><div class=\"zlabel\">🎚️ QoS + enforcement</div><div class=\"term mini\"><span class=\"g\">Guaranteed: requests==limits (cpu+mem, all)</span>\r\n<span class=\"g\">Burstable: partial  ·  BestEffort: none</span>\r\n<span class=\"g\">eviction: BestEffort → Burst&gt;req → Guaranteed</span>\r\n<span class=\"r\">mem over limit → OOMKilled 137</span>\r\n<span class=\"y\">cpu over limit → throttled</span>\r\n<span class=\"p\">$</span> kubectl get pod P -o jsonpath='{.status.qosClass}'</div></div>\r\n</div>\r\n<div class=\"card\"><div class=\"zlabel\">🧠 Facts worth a job offer</div>\r\n<ul>\r\n<li>ConfigMap = whiteboard, Secret = safe — same delivery, different trust · both ~1 MiB, namespaced</li>\r\n<li>Base64 ≠ encryption — real layers: etcd encryption-at-rest + RBAC (+ external secret managers)</li>\r\n<li>Default deny: no Role = no access; default SA has zero permissions; audit with <code>can-i --as</code></li>\r\n<li>RoleBinding may bind a ClusterRole (namespaced reach) · cluster-scoped resources force ClusterRoles</li>\r\n<li>SecurityContext = Linux perms; PSS (Privileged/Baseline/Restricted) = namespace-enforced policy; PSP is gone (v1.25)</li>\r\n<li>Requests → scheduling · Limits → CPU throttle / mem OOMKill · QoS → eviction order</li>\r\n</ul></div>\r\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#gloss\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#finale\">finale ▶</a></span><span>Page 25</span></div></div>\r\n\r\n\r\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">FINALE</span><h2 id=\"what-you-can-do-now\">🗺️ What You Can Do Now</h2><span class=\"dbadge\">🎓 Book 02 complete</span></div>\r\n<p>Book 01 gave you the machine. This book gave it <b>manners</b> — config, secrets, permissions, and a resource contract.</p>\r\n<div class=\"mtree\"><b>☸️ POD</b> <span class=\"g\">— fully dressed now:</span>\r\n├── <u>⚙️ ConfigMap</u>   <span class=\"g\">plain config → env / files (hot-reload rules known)</span>\r\n├── <u>🔐 Secret</u>      <span class=\"g\">sensitive data — encoded ≠ encrypted, RBAC-gated</span>\r\n├── <u>🪪 ServiceAccount</u> <span class=\"g\">+ Role/RoleBinding = exactly what it may do</span>\r\n├── <u>🛡️ SecurityContext</u> <span class=\"g\">runAsNonRoot · roFS · caps (PSS-enforced)</span>\r\n└── <u>📊 requests/limits</u> <span class=\"g\">→ scheduler placement, throttle/OOM, QoS class</span></div>\r\n<h3 id=\"you-can-now\">✅ You can now…</h3>\r\n<ul>\r\n<li>Decouple config from images and pick env-vs-volume <i>knowing</i> the hot-reload consequences</li>\r\n<li>Dismantle the \"Secrets are encrypted\" myth and name the four real protection layers</li>\r\n<li>Write Role + RoleBinding, reuse a ClusterRole per-namespace, and audit anyone with <code>can-i --as</code></li>\r\n<li>Harden a Pod (SecurityContext) and enforce it fleet-wide with PSS namespace labels</li>\r\n<li>Predict throttle-vs-OOMKill, and read a 137 exit code like a native speaker</li>\r\n<li>Trigger — and diagnose — every failure mode in Labs 1–4 on demand</li>\r\n</ul>\r\n<div class=\"callout co-key\"><span class=\"ico\">🎓</span><div><b>Where to next — Book 03 · Services &amp; Networking Deep Dive:</b> LoadBalancer, Ingress &amp; TLS termination, NetworkPolicy, CoreDNS internals, and the Gateway API. Your Pods can now be configured, secured, and budgeted — Book 03 teaches the world how to <i>reach</i> them.</div></div>\r\n<div class=\"center\">— End of Book 02 · 🎬 —</div>\r\n<div class=\"pgfoot\"><span>📘 Book 02 · Config, Secrets &amp; RBAC</span><span><a href=\"#cheat\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a></span><span>Page 26</span></div></div>\r\n\r\n\r\n","toc":[{"id":"config-secrets-amp-access-control","text":"CONFIG · SECRETS&amp; ACCESS CONTROL","level":1},{"id":"contents-click-any-row","text":"Contents — click any row","level":2},{"id":"configmaps-what-amp-why","text":"⚙️ ConfigMaps — What &amp; Why","level":2},{"id":"create-one-three-ways","text":"🛠️ Create one — three ways","level":3},{"id":"creating-amp-mounting-configmaps","text":"📥 Creating &amp; Mounting ConfigMaps","level":2},{"id":"two-consumption-methods-they-behave-differently","text":"🔌 Two consumption methods — they behave differently","level":3},{"id":"hot-reload-what-actually-updates","text":"🔄 Hot-Reload — What Actually Updates","level":2},{"id":"secrets-vs-configmaps","text":"🔐 Secrets — vs ConfigMaps","level":2},{"id":"secret-types-amp-creation","text":"🏷️ Secret Types &amp; Creation","level":2},{"id":"creation-imperative-amp-declarative","text":"🛠️ Creation — imperative &amp; declarative","level":3},{"id":"mounting-secrets-imagepullsecrets","text":"📤 Mounting Secrets + imagePullSecrets","level":2},{"id":"imagepullsecrets-auth-for-pulling-images","text":"🖼️ imagePullSecrets — auth for pulling images","level":3},{"id":"base64-encryption-the-truth","text":"🔓 Base64 ≠ Encryption — The Truth","level":2},{"id":"the-four-real-layers-of-secret-protection","text":"🧅 The four real layers of Secret protection","level":3},{"id":"rbac-the-big-idea","text":"🪪 RBAC — The Big Idea","level":2},{"id":"roles-amp-rolebindings","text":"📜 Roles &amp; RoleBindings","level":2},{"id":"clusterroles-amp-when-to-use-which","text":"🌐 ClusterRoles &amp; When to Use Which","level":2},{"id":"serviceaccounts","text":"👷 ServiceAccounts","level":2},{"id":"the-full-chain-badge-rulebook","text":"🔗 The full chain — badge → rulebook","level":3},{"id":"securitycontext","text":"🛡️ SecurityContext","level":2},{"id":"pod-security-standards","text":"🚨 Pod Security Standards","level":2},{"id":"requests-amp-limits","text":"📊 Requests &amp; Limits","level":2},{"id":"requests-the-promise","text":"REQUESTS — the promise","level":3},{"id":"limits-the-ceiling","text":"LIMITS — the ceiling","level":3},{"id":"qos-classes","text":"🎚️ QoS Classes","level":2},{"id":"configmap-prove-env-hot-reload","text":"🔬 ConfigMap — Prove Env ≠ Hot-Reload","level":2},{"id":"secret-encoded-not-encrypted","text":"🔐 Secret — Encoded, Not Encrypted","level":2},{"id":"rbac-can-i-as-a-serviceaccount","text":"🪪 RBAC — Can-I as a ServiceAccount","level":2},{"id":"trigger-an-oomkill-on-purpose","text":"💥 Trigger an OOMKill on Purpose","level":2},{"id":"self-check-quiz","text":"✅ Self-Check Quiz","level":2},{"id":"answer-key-scoring","text":"🗝️ Answer Key + Scoring","level":2},{"id":"glossary","text":"📚 Glossary","level":2},{"id":"one-page-cheat-sheet","text":"📄 One-Page Cheat Sheet","level":2},{"id":"what-you-can-do-now","text":"🗺️ What You Can Do Now","level":2},{"id":"you-can-now","text":"✅ You can now…","level":3}],"words":6168,"assets":[]};